parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "language": {
      "type": "string",
      "enum": [
        "de",
        "en"
      ]
    },
    "queue": {
      "type": "string",
      "enum": [
        "Customer Service",
        "Returns and Exchanges",
        "Billing and Payments",
        "Product Support"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "very_low",
        "low",
        "medium",
        "high",
        "critical"
      ]
    },
    "reason": {
      "type": "string"
    },
    "draft_reply": {
      "type": "string"
    },
    "policy_sections": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "language",
    "queue",
    "priority",
    "reason",
    "draft_reply",
    "policy_sections"
  ]
}
